-- PowerPrep Quest — full seed (schema + content). Safe to run multiple
-- times; guarded by a row-count check at the end of the script.
BEGIN;

CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS sessions (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS profile (
  user_id INTEGER PRIMARY KEY REFERENCES users(id),
  xp INTEGER NOT NULL DEFAULT 0,
  streak INTEGER NOT NULL DEFAULT 0,
  last_checkin TEXT,
  active_track TEXT NOT NULL DEFAULT 'PL200',
  exams_passed INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS questions (
  id SERIAL PRIMARY KEY,
  track TEXT NOT NULL,
  domain TEXT NOT NULL,
  question_text TEXT NOT NULL,
  options TEXT NOT NULL,
  correct_index INTEGER NOT NULL,
  explanation TEXT NOT NULL,
  why_wrong TEXT NOT NULL,
  difficulty TEXT NOT NULL DEFAULT 'medium',
  tags TEXT NOT NULL DEFAULT '[]',
  is_gemba INTEGER NOT NULL DEFAULT 0,
  doc_link TEXT
);

CREATE TABLE IF NOT EXISTS question_progress (
  user_id INTEGER NOT NULL REFERENCES users(id),
  question_id INTEGER NOT NULL REFERENCES questions(id),
  attempts INTEGER NOT NULL DEFAULT 0,
  correct_attempts INTEGER NOT NULL DEFAULT 0,
  mastered INTEGER NOT NULL DEFAULT 0,
  last_attempt_at TIMESTAMPTZ,
  PRIMARY KEY (user_id, question_id)
);

CREATE TABLE IF NOT EXISTS case_studies (
  id SERIAL PRIMARY KEY,
  track TEXT NOT NULL,
  title TEXT NOT NULL,
  scenario TEXT NOT NULL,
  constraints TEXT NOT NULL,
  stakeholders TEXT NOT NULL DEFAULT '[]'
);

CREATE TABLE IF NOT EXISTS case_study_questions (
  id SERIAL PRIMARY KEY,
  case_study_id INTEGER NOT NULL REFERENCES case_studies(id),
  step_order INTEGER NOT NULL,
  question_text TEXT NOT NULL,
  options TEXT NOT NULL,
  correct_index INTEGER NOT NULL,
  explanation TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS challenges (
  id SERIAL PRIMARY KEY,
  track TEXT NOT NULL,
  engine TEXT NOT NULL,
  title TEXT NOT NULL,
  prompt TEXT NOT NULL,
  starter_code TEXT NOT NULL,
  mock_data TEXT NOT NULL,
  expected_result TEXT NOT NULL,
  hint TEXT NOT NULL,
  solution TEXT NOT NULL,
  difficulty TEXT NOT NULL DEFAULT 'medium'
);

CREATE TABLE IF NOT EXISTS challenge_progress (
  user_id INTEGER NOT NULL REFERENCES users(id),
  challenge_id INTEGER NOT NULL REFERENCES challenges(id),
  solved INTEGER NOT NULL DEFAULT 0,
  attempts INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, challenge_id)
);

CREATE TABLE IF NOT EXISTS flashcards (
  id SERIAL PRIMARY KEY,
  track TEXT NOT NULL,
  category TEXT NOT NULL,
  front TEXT NOT NULL,
  back TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS flashcard_progress (
  user_id INTEGER NOT NULL REFERENCES users(id),
  flashcard_id INTEGER NOT NULL REFERENCES flashcards(id),
  ease_factor REAL NOT NULL DEFAULT 2.5,
  interval_days REAL NOT NULL DEFAULT 0,
  repetitions INTEGER NOT NULL DEFAULT 0,
  due_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_reviewed_at TIMESTAMPTZ,
  PRIMARY KEY (user_id, flashcard_id)
);

CREATE TABLE IF NOT EXISTS skill_nodes (
  id TEXT PRIMARY KEY,
  track TEXT NOT NULL,
  name TEXT NOT NULL,
  domain TEXT NOT NULL,
  description TEXT NOT NULL,
  prerequisites TEXT NOT NULL DEFAULT '[]',
  x REAL NOT NULL DEFAULT 0,
  y REAL NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS skill_node_awards (
  user_id INTEGER NOT NULL REFERENCES users(id),
  node_id TEXT NOT NULL REFERENCES skill_nodes(id),
  awarded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, node_id)
);

CREATE TABLE IF NOT EXISTS exam_attempts (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id),
  track TEXT NOT NULL,
  score_1000 INTEGER NOT NULL,
  correct_count INTEGER NOT NULL,
  total_count INTEGER NOT NULL,
  passed INTEGER NOT NULL,
  domain_breakdown TEXT NOT NULL,
  taken_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Bail out early if already seeded, without erroring the whole script.
DO $$
BEGIN
  IF (SELECT COUNT(*) FROM questions) > 0 THEN
    RAISE NOTICE 'Already seeded — skipping. Truncate the tables first if you want to reseed.';
  ELSE
    -- questions
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'You need a column that automatically sums the Estimated Revenue of all related Opportunity records on an Account. The value must be recalculated by the system on a schedule and should not count against custom API limits when read. Which column type should you create?', '["Calculated column","Rollup column","Business-required lookup column","Power Automate flow updating a whole number column"]', 1, 'Rollup columns aggregate values (SUM, COUNT, MIN, MAX, AVG) from related records and are recalculated asynchronously by the system (every ~12 hours by default, or on-demand/manually triggered). They are the native Dataverse mechanism for this exact scenario.', '["Calculated columns compute synchronously from columns on the SAME row (or related parent via lookup), not aggregates across a one-to-many child collection — they cannot sum child records.","Correct — rollup columns are purpose-built for aggregating related child records on a recurring schedule.","A lookup column just references a related record; it has no aggregation behavior.","This would work but duplicates native platform functionality, adds maintenance overhead, and consumes flow runs/API capacity for something Dataverse already does out of the box."]', 'easy', '["dataverse","columns","rollup"]', 0, 'https://learn.microsoft.com/power-apps/maker/data-platform/define-field-type#rollup');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'A table needs a relationship so that when a parent Account record is deactivated, all related custom Equipment records are automatically deactivated too, but deleting the Account should NOT delete the Equipment records. Which relationship behavior should you configure?', '["Parental","Referential, Restrict Delete","Configurable cascading with Deactivate = Cascade All, Delete = Cascade None","Connection"]', 2, 'Configurable cascading relationship behavior lets you set each action (Assign, Share, Reparent, Unshare, Delete, Merge) independently. Setting Deactivate to Cascade All and Delete to Cascade None (or Remove Link) achieves exactly this split requirement.', '["Parental behavior cascades delete and deactivate together — you cannot decouple them, so the Equipment records would also be deleted.","Referential, Restrict Delete blocks deleting the Account while related Equipment exists — it does not handle deactivation cascading at all.","Correct — configurable cascading is the only behavior that lets Deactivate and Delete be configured independently.","A Connection record is an informal, non-structural relationship used for ad-hoc associations; it has no cascading behavior configuration."]', 'medium', '["dataverse","relationships","cascading"]', 0, 'https://learn.microsoft.com/power-apps/maker/data-platform/create-edit-entity-relationships');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'You are designing a business rule that must run both on the form (client-side, for immediate user feedback) and server-side (so it still applies to records created via the API or Power Automate). Which scope should you choose when creating the business rule?', '["Entity","Specific form","Entity scope with \"All Forms\"","No scope setting is needed; business rules always run everywhere"]', 0, 'When a business rule scope is set to "Entity," it runs both on all forms of the table AND server-side (including API, bulk operations, and Power Automate), whereas "Specific form(s)" scope only runs client-side on the selected form(s).', '["Correct — Entity-scoped business rules execute on both the client (every form) and the server, satisfying both requirements.","Specific form scope only triggers on that form in the browser; it never fires for server-side/API-created records.","\"All Forms\" is not a distinct scope option — the real options are Entity, or specific form selections; Entity already implies all forms plus server-side.","Scope absolutely matters — form-scoped rules never execute for server-side operations like flows or the Web API."]', 'medium', '["dataverse","business-rules"]', 0, 'https://learn.microsoft.com/power-apps/maker/data-platform/create-business-rules-templates-for-entity');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'Which Dataverse feature should you use to enforce that a "Work Order" cannot be set to Status = Closed unless a related "Inspection" record with Result = Passed exists, where the rule is too complex for a business rule?', '["Classic workflow (real-time)","Business rule","Plug-in registered on the PreOperation stage of Update","Power Automate flow triggered after update"]', 2, 'A synchronous plug-in on the PreOperation stage can inspect related records and throw an InvalidPluginExecutionException to block the save transactionally before it commits — this is the standard pattern for complex, must-be-enforced validation logic beyond what business rules support.', '["Classic real-time workflows can run synchronously but have limited logic capability and are deprecated/not recommended for new complex validation; plug-ins are the supported extensibility point for this.","Business rules only support simple condition/action logic against columns on the current form/table; they cannot easily query related child collections with complex conditions.","Correct — a synchronous PreOperation plug-in can block the transaction entirely if validation fails, which is required here.","Power Automate flows triggered \"after update\" run asynchronously AFTER the save has already committed, so they cannot prevent the Closed status from being saved in the first place."]', 'hard', '["dataverse","plugins","business-logic"]', 1, 'https://learn.microsoft.com/power-apps/developer/data-platform/plug-ins');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'You need to import 50,000 legacy defect records into a new "Defect" table in Dataverse, mapping columns from a CSV and preserving created-on dates. Which tool is the most appropriate out-of-the-box option?', '["Power Automate \"Create a new row\" loop over each CSV row","Dataverse Import Data wizard (Get Data / data import)","Manually copy-paste into a view","Export the CSV as a Canvas App local collection"]', 1, 'The native Import Data wizard (or Get Data from Excel/CSV) in Power Apps/Dataverse is designed for bulk record creation with field mapping templates, duplicate detection, and supports preserving historical dates via the "Override Created On" bulk data migration setting.', '["A flow looping 50,000 times is slow, hits API/throttling limits quickly, and is far more fragile than the built-in bulk import tool.","Correct — the Import Data wizard is purpose-built for exactly this bulk migration scenario, including field mapping and duplicate detection.","Manually copying 50,000 rows is impractical and error-prone.","A local Canvas App collection is in-memory, client-side, and not a Dataverse persistence or migration mechanism."]', 'easy', '["dataverse","data-migration"]', 1, 'https://learn.microsoft.com/power-platform/admin/import-data');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'An alternate key is configured on the "Machine" table using the "AssetTag" column. What is the primary benefit of this configuration for integration scenarios?', '["It automatically creates a unique index visible to end users on forms","It allows external systems to upsert records via the Web API using AssetTag instead of the internal GUID","It encrypts the AssetTag column","It enables offline mobile sync for that column"]', 1, 'Alternate keys let external systems reference and upsert (update-or-insert) Dataverse records using a business-meaningful value (like AssetTag) in the Web API URL, instead of needing to know the internal primary key GUID.', '["Alternate keys do create a unique index at the database level, but their main integration purpose is enabling upsert operations by that key — not a UI feature.","Correct — alternate keys enable external systems to address and upsert records by a business key rather than the GUID.","Alternate keys have nothing to do with field-level encryption.","Offline mobile sync behavior is unrelated to alternate key configuration."]', 'medium', '["dataverse","alternate-keys","integration"]', 1, 'https://learn.microsoft.com/power-apps/developer/data-platform/define-alternate-keys-entity');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'You want users to see a warning (not a hard block) when they enter an Order Quantity greater than Available Stock, and you want this to require zero code or flows. What should you configure?', '["A business rule with a recommendation-level action (\"Show error message\")","A business rule with a warning-level action","A real-time workflow that cancels the save","A plug-in throwing a warning exception"]', 1, 'Business rule actions include "Show Error Message" (blocks save) and a separate warning/recommendation notification that informs the user without preventing the save — exactly matching a non-blocking warning requirement, with no code.', '["\"Show error message\" in a business rule blocks the save — that is a hard block, not a soft warning.","Correct — business rules support non-blocking notification messages, satisfying the \"warn but don''t block\" and \"no code\" requirements.","Canceling the save is a hard block and requires more complex logic than a simple business rule.","Throwing any exception from a plug-in blocks the save and requires custom code — both violate the requirements."]', 'medium', '["dataverse","business-rules"]', 1, 'https://learn.microsoft.com/power-apps/maker/data-platform/create-business-rules-templates-for-entity');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Security', 'Your organization has Business Units for "North Plant" and "South Plant." A security role is set with the "Read" privilege on the Work Order table at the "Business Unit" (Local) access level. A user in North Plant should NOT be able to read Work Orders owned by users in South Plant. Which access level actually satisfies this?', '["User (Basic)","Business Unit","Parent: Child Business Units","Organization"]', 1, 'Business Unit level access restricts visibility to records owned by users within the SAME business unit as the user. This is exactly the isolation required between North and South Plant, assuming they are not parent/child of each other.', '["User (Basic) level would restrict the user to seeing only their OWN records, which is too restrictive — they need to see their whole plant''s records.","Correct — Business Unit level scopes visibility to the user''s own business unit only, isolating North from South.","Parent: Child Business Units would let a user see records in child business units too, which is wider than required and could leak South Plant data if the BUs are hierarchically related.","Organization level grants visibility across the entire org, which is far too broad and violates the isolation requirement."]', 'medium', '["security","business-units","access-levels"]', 1, 'https://learn.microsoft.com/power-platform/admin/security-roles-privileges');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Security', 'You need to grant a contractor temporary access to a single specific Opportunity record without creating a new security role or changing the business unit structure. What should you use?', '["Field Security Profile","Sharing (Share button on the record)","Hierarchy security","Team ownership of the whole table"]', 1, 'Record sharing grants specific privileges (Read, Write, etc.) on an individual record instance to a specific user or team, independent of their security role, and can be revoked at any time — ideal for one-off, temporary, record-level access.', '["Field Security Profiles control access to specific COLUMNS flagged as secured, not access to whole records.","Correct — sharing a single record is the lightweight, instance-level mechanism designed for exactly this scenario.","Hierarchy security grants access based on manager/position hierarchies across many records, not a single ad-hoc record for a contractor outside that hierarchy.","Granting team ownership of an entire table-level privilege is far broader than \"one specific record\" and requires role/team administration overhead."]', 'easy', '["security","sharing"]', 0, 'https://learn.microsoft.com/power-platform/admin/share-record-team');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Security', 'A "Salary" column on the Employee table must be visible only to HR Managers, even though many other roles have Read access to the Employee table itself. What is the correct combination of configuration steps?', '["Create a separate \"Confidential Employee\" table just for salary data","Enable field-level security on the Salary column, then grant Read access via a Field Security Profile assigned to HR Managers","Set the Salary column to \"Business Required\" and restrict the form","Use a business rule to hide the column for non-HR roles"]', 1, 'Field-level security is enabled per-column, and access (Read/Create/Update) to that secured field is then granted only through Field Security Profiles, which are assigned to specific users or teams (here, HR Managers) — independent of table-level security roles.', '["Splitting into a separate table is a major schema redesign that is unnecessary when field-level security solves this natively.","Correct — this is precisely what field-level security plus Field Security Profiles is designed for.","\"Business Required\" only controls whether a value must be entered; it has no bearing on who can view the column.","Business rules can hide fields on a FORM, but that is a client-side UI convenience only — the data is still exposed via views, reports, and the API, so it is not real security."]', 'medium', '["security","field-security"]', 0, 'https://learn.microsoft.com/power-platform/admin/field-level-security');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Security', 'A Quality Manager should be able to see Defect records owned by anyone reporting to them (based on the manager hierarchy in Microsoft Entra ID / the Dataverse "Manager" lookup), without being given Business Unit or Organization-level read access. What should you enable?', '["Positional hierarchy security model","Manager hierarchy security model","Custom hierarchy security model","Team-based ownership only"]', 1, 'Manager hierarchy security automatically grants a manager Read (and optionally Write) access to records owned by their direct and indirect subordinates, based on the "Manager" field — without broadening access to the whole business unit.', '["Positional hierarchy uses a separately defined position structure (not the Manager field) and is better suited when org chart and reporting chain differ from HR manager relationships.","Correct — Manager hierarchy security directly uses the Manager lookup to cascade visibility down the reporting chain.","Dataverse does not have a security model literally named \"Custom hierarchy\" — the two hierarchy models are Manager and Position.","Team-based ownership alone does not automatically grant visibility based on a manager/subordinate relationship."]', 'medium', '["security","hierarchy-security"]', 1, 'https://learn.microsoft.com/power-platform/admin/hierarchy-security');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Security', 'Which statement about Dataverse Teams is TRUE?', '["An Owner Team can own records and have security roles assigned directly to it","An Access Team must have security roles assigned directly to it","A user automatically loses their individual security role privileges when added to any team","Teams can only contain users from the same Business Unit as the team"]', 0, 'Owner Teams are a distinct security principal: they can own records directly and can have one or more security roles assigned to the team itself, which combine with each member''s own roles.', '["Correct — Owner Teams can own records and be assigned security roles directly.","Access Teams (used with Access Team Templates) get their access via record sharing based on a template, not by having roles assigned directly to the team.","Security privileges are additive — a user keeps their own role privileges AND gains any team-assigned role privileges.","A team''s members can come from different business units; the team itself belongs to one business unit, but members are not restricted to it."]', 'medium', '["security","teams"]', 0, 'https://learn.microsoft.com/power-platform/admin/create-edit-teams');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Canvas Apps', 'In a Canvas App connected to Dataverse, you want a gallery of "Open" Work Orders sorted by CreatedOn descending, and the data source has 50,000 rows. Which formula pattern ensures the filter/sort is delegated to the server instead of only operating on the first 500/2000 rows loaded locally?', '["SortByColumns(Filter(WorkOrders, Status.Value = \"Open\"), \"CreatedOn\", Descending)","Sort(Filter(Collect(colWO, WorkOrders)), CreatedOn)","FirstN(Sort(WorkOrders, CreatedOn), 50)","Filter(ClearCollect(colWO, WorkOrders), Status.Value=\"Open\")"]', 0, 'Filter and SortByColumns against a Dataverse table (using delegable operators like simple equality on a choice/option set .Value, and a direct column name) are delegable, meaning the server (Dataverse) performs the filtering/sorting across ALL rows, not just the locally cached page.', '["Correct — Filter with a simple equality check and SortByColumns with a plain column name are both delegable against Dataverse, so the full 50,000-row table is filtered/sorted server-side.","Collect() pulls data into a local collection first (subject to the row limit), defeating delegation — the Filter afterward only operates on whatever was already loaded locally.","Sort() is NOT a delegable function in Canvas Apps (SortByColumns is used for delegation); using Sort directly on a large table risks a non-delegable warning and incomplete results.","ClearCollect loads data into memory first (again capped by the row limit setting), so any Filter afterward only sees the already-loaded subset."]', 'hard', '["canvas-apps","delegation","power-fx"]', 1, 'https://learn.microsoft.com/power-apps/maker/canvas-apps/delegation-overview');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Canvas Apps', 'You need a Canvas App button that both creates a new "Inspection" record in Dataverse AND updates the related "WorkOrder" record''s LastInspectedDate column in one action. Which Power Fx function is correct for writing (creating or updating) a Dataverse record?', '["LookUp()","Patch()","Filter()","Collect() only"]', 1, 'Patch() is the Power Fx function for creating or updating records in a data source. You can call Patch twice (once per table) or combine logic, e.g. Patch(Inspections, Defaults(Inspections), {...}) to create, and Patch(WorkOrders, workOrderRecord, {LastInspectedDate: Now()}) to update.', '["LookUp() only reads and returns a single matching record; it cannot write data.","Correct — Patch() is the write (create/update) function in Power Fx.","Filter() only reads and returns a filtered table; it does not modify data.","Collect() can add new records to a LOCAL collection or append a record to a data source, but it does not support updating existing records the way Patch does, and is not the standard function for updating a related record''s column."]', 'easy', '["canvas-apps","power-fx","patch"]', 1, 'https://learn.microsoft.com/power-platform/power-fx/reference/function-patch');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Canvas Apps', 'A Canvas App must work when a field technician has no internet connectivity in a remote plant, allowing them to view assigned Work Orders and save Inspection results, syncing later. What should you implement?', '["Increase the Data row limit in app settings","Offline profiles with SaveData()/LoadData() or the Power Apps mobile offline capability for model-driven-style data","A Power Automate flow with a retry policy","Publish the app with \"Always Online\" disabled"]', 1, 'True offline support in Canvas Apps requires explicitly caching needed data locally (e.g., via SaveData/LoadData to local collections, or configuring an offline profile for the mobile player) so the app can read/write data without connectivity and sync changes when back online.', '["The Data row limit setting only changes how many rows are cached in non-delegable queries; it does not provide offline read/write capability.","Correct — explicit offline data handling (SaveData/LoadData patterns or offline profiles) is required to support disconnected use.","Power Automate flows require connectivity to execute; a retry policy does not help a fully offline mobile scenario.","\"Always Online\" is not a real Canvas App publish setting — offline capability must be deliberately engineered into the app."]', 'hard', '["canvas-apps","offline"]', 1, 'https://learn.microsoft.com/power-apps/maker/canvas-apps/offline-apps');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Canvas Apps', 'Which component feature should you use to package a reusable "Defect Severity Badge" control (with its own custom properties) so it can be shared and reused consistently across multiple Canvas Apps in your environment?', '["Canvas Component in a Component Library","A screen template duplicated into each app","A SharePoint list","Named Formulas"]', 0, 'Component Libraries let you build Canvas Components with custom input/output properties and publish them so multiple apps can import and reuse the exact same component, with centralized updates.', '["Correct — Component Libraries are the designed-for mechanism for sharing reusable UI components with custom properties across apps.","Duplicating a screen into every app creates copies that drift out of sync and must be manually updated everywhere.","A SharePoint list stores data, not reusable UI components/logic.","Named Formulas (App OnStart-level calculated values) are for app-wide calculated values/state, not reusable visual controls."]', 'medium', '["canvas-apps","components"]', 0, 'https://learn.microsoft.com/power-apps/maker/canvas-apps/create-component-library');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Canvas Apps', 'A form in a Canvas App must prevent submission unless both "InspectorName" and "DefectPhoto" are provided, showing inline validation. What is the most appropriate approach?', '["Set DisplayMode of the Submit button to Disabled permanently","Use the form''s Valid property combined with required fields on the Edit form card, and bind the Submit button''s DisplayMode to If(Form1.Valid, Edit, Disabled)","Write a Power Automate flow to reject invalid submissions after the fact","Use a timer control to delay submission"]', 1, 'Canvas Form controls expose a .Valid property that reflects whether all required fields pass validation; binding the Submit button''s DisplayMode to this property (disabling it until valid) gives real-time inline validation feedback without extra code.', '["Permanently disabling the button prevents ANY submission, including valid ones.","Correct — this is the standard Canvas Forms pattern for required-field, inline validation before allowing submit.","Rejecting after submission is reactive, not preventive, and provides a poor user experience plus wastes a flow run on something that should block at the UI.","A timer control has nothing to do with field validation."]', 'medium', '["canvas-apps","forms","validation"]', 1, 'https://learn.microsoft.com/power-apps/maker/canvas-apps/working-with-forms');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Model-Driven Apps', 'You want to guide users through a multi-stage process (New -> In Review -> Approved -> Closed) on the "Change Request" table, visually showing the current stage and required steps at the top of the form. What should you configure?', '["A Business Process Flow (BPF)","A Classic Workflow","A Dashboard","A Quick Create Form"]', 0, 'Business Process Flows render a visual stage/step indicator at the top of the model-driven app form, guiding users through defined stages with required fields per step — exactly matching this requirement.', '["Correct — BPFs are the specific feature for visual, stage-based guided processes on a form.","Classic workflows run business logic in the background; they have no visual on-form stage indicator for users.","Dashboards aggregate views/charts for reporting; they are not a per-record guided process UI.","Quick Create Forms are simplified forms for fast record creation, not guided multi-stage processes."]', 'easy', '["model-driven-apps","business-process-flows"]', 1, 'https://learn.microsoft.com/power-automate/business-process-flows-overview');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Model-Driven Apps', 'A model-driven app sitemap needs a new area called "Quality" containing a group "Inspections" with subareas for the Defect and Inspection tables, visible only to users with the "Quality Inspector" security role. What governs the visibility of that sitemap area for different users?', '["The subarea''s \"Enable Security\" setting tied to a privilege the role must have (e.g., Read on the underlying table)","Renaming the area to include the role name","Setting the app itself to private and sharing it only with Quality Inspectors","Hiding the area using a business rule"]', 0, 'Sitemap subareas are tied to table (or other) privileges; a user only sees a subarea if their security role grants the required privilege (commonly Read) on the entity the subarea points to. This is how model-driven navigation naturally reflects security roles.', '["Correct — subarea visibility in the sitemap follows the user''s privileges on the referenced table/entity.","Naming has no effect on visibility or access.","Sharing the app model (app-level security roles the app is enabled for) controls who can open the APP, but navigation items within it still respect the underlying table privileges — and this is a blunter, less precise control than privilege-based subarea visibility.","Business rules operate on form logic for a single table''s fields, not sitemap navigation structure."]', 'medium', '["model-driven-apps","sitemap","security"]', 1, 'https://learn.microsoft.com/power-apps/maker/model-driven-apps/configure-sitemap-app-designer');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Model-Driven Apps', 'Which model-driven app form type is loaded first and optimized for performance by loading only visible tabs/fields, with additional tabs lazy-loaded as the user scrolls or clicks?', '["Quick View Form","Main Form (Unified Interface responsive/optimized rendering)","Card Form","Quick Create Form"]', 1, 'The Main Form in the Unified Interface uses performance optimizations, including lazy-loading of tab content not immediately visible, to improve load time on forms with many tabs/sections.', '["A Quick View Form is a read-only snippet embedded within another form to show related record data, not the primary form type.","Correct — Main Forms in Unified Interface are optimized to progressively/lazy-load content as the user interacts with tabs.","Card Forms are compact layouts used in specific controls (like the Kanban board/stream), not the general-purpose main form.","Quick Create Forms are simplified single-column forms for rapid record creation in a side panel, unrelated to lazy-loading tab behavior."]', 'medium', '["model-driven-apps","forms"]', 0, 'https://learn.microsoft.com/power-apps/maker/model-driven-apps/create-design-forms-user-experience');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Model-Driven Apps', 'You need a view that shows only Defect records where Severity = "Critical" AND Status = "Open", available to all users of the Quality app by default when they open the Defects subarea. What should you configure?', '["A Personal View saved by the admin","A System View marked as the Default View for the entity (or set as the default on the app''s navigation)","A Quick Find view only","An Advanced Find saved query shared with \"Everyone\""]', 1, 'System (public) views are available to all users; marking one as the default view for the table (or configuring it as the default in the app) ensures it loads automatically when users navigate to that subarea.', '["Personal views are private to the user who created them (unless explicitly shared) and are not automatically the default for everyone.","Correct — a System View set as default is what loads automatically for all users by default.","Quick Find views control what Quick Find searches against; they are not a general filtered default list view.","An Advanced Find saved view shared with Everyone gives everyone access to run it, but it still does not automatically become the DEFAULT view loaded without additional configuration."]', 'medium', '["model-driven-apps","views"]', 1, 'https://learn.microsoft.com/power-apps/maker/model-driven-apps/create-edit-views');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Automate', 'A cloud flow should trigger immediately whenever a new "Defect" row is created in Dataverse, but you specifically only want it to fire on manual user creation, not on bulk data imports or integration inserts. Which trigger configuration achieves this?', '["\"When a row is added, modified or deleted\" with \"Run as\" set to the flow owner and no additional filters","The Dataverse trigger''s \"Scope\" filter combined with checking a condition on an attribute that only manual UI creation sets, since Dataverse triggers alone cannot distinguish origin","A Power Automate \"Instant cloud flow\" trigger","A scheduled flow running every 5 minutes"]', 1, 'Dataverse triggers fire for creation regardless of origin (UI, import, API) — there is no native "created via UI only" trigger filter. The practical solution is to combine the trigger with a condition check (e.g., a column or context value only set during manual entry) since bulk import tools can optionally bypass flows, but that is an import-time setting, not a trigger configuration — making a post-trigger condition the dependable approach within the flow itself.', '["This configuration fires on ALL creation regardless of source, which does not satisfy the \"manual only\" requirement.","Correct — because the Dataverse trigger cannot natively distinguish origin, the supported pattern is to add a condition/check inside the flow to filter out non-manual creations.","An instant cloud flow trigger is manually invoked by a user action (like a button), not automatically triggered on table row creation — it does not match \"triggers immediately whenever a new Defect row is created.\"","A 5-minute polling schedule is not immediate and does not inherently distinguish creation origin either."]', 'hard', '["power-automate","dataverse-trigger"]', 1, 'https://learn.microsoft.com/power-automate/triggers-introduction');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Automate', 'A flow processes a list of 10,000 Work Orders using "Apply to each," and you need to speed it up because each iteration is independent of the others. What should you enable?', '["Increase the flow''s run frequency","Concurrency Control on the Apply to each action, raising the degree of parallelism","Add a Delay action before each iteration","Switch the trigger to \"Recurrence\""]', 1, 'Concurrency Control (available on Apply to each and on triggers) allows multiple iterations to run in parallel instead of strictly sequentially, which significantly reduces total run time for large, independent iteration sets (default max is 50 in Apply to each).', '["Run frequency controls how often the flow STARTS, not how fast a single run processes its loop.","Correct — Concurrency Control lets independent iterations run in parallel, directly addressing the speed problem.","Adding delays would make the loop slower, not faster.","Changing the trigger type does not affect loop execution speed within a single run."]', 'medium', '["power-automate","performance","concurrency"]', 1, 'https://learn.microsoft.com/power-automate/error-handling#concurrency-control');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Automate', 'An approval flow for Purchase Requisitions over $10,000 must send an adaptive card to the requester''s manager, wait for Approve/Reject, and if no response in 48 hours, escalate to the next-level manager. Which combination of actions is most appropriate?', '["A single \"Send an email\" action with a hard deadline","Start and wait for an approval action configured with a timeout, followed by a condition that checks the outcome and branches to a second approval for escalation","A Power Automate desktop flow","A Dataverse business rule with a 48-hour timer"]', 1, 'The Approvals connector''s "Start and wait for an approval" action supports a configurable duration/timeout; combined with a Condition action checking whether a response was received in time, you can branch into a second escalation approval sent to the next-level manager.', '["A plain email has no built-in approve/reject response handling or escalation logic.","Correct — this is the standard supported pattern combining Approvals timeout with conditional escalation branching.","Power Automate Desktop flows automate UI/legacy desktop applications; they are not the right tool for a cloud-based approval workflow with adaptive cards.","Business rules operate on form field logic in real time, not asynchronous multi-day timers or escalation routing."]', 'hard', '["power-automate","approvals"]', 1, 'https://learn.microsoft.com/power-automate/create-approval-flows');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Automate', 'A flow calling an external REST API occasionally fails due to transient network timeouts. Without writing custom retry logic, how can you make the HTTP action automatically retry on failure?', '["Add a Delay action after the HTTP call","Configure the action''s built-in Retry Policy (Settings) with a count, interval, and type (e.g., Exponential)","Duplicate the HTTP action three times in sequence","Set the flow trigger concurrency to 1"]', 1, 'Most Power Automate actions (including HTTP and most connectors) expose a Retry Policy in their action Settings, letting you define retry count and interval (fixed or exponential) without any extra actions or custom logic.', '["A delay after the call does nothing to retry a failed call — the call has already failed and completed.","Correct — the built-in Retry Policy setting on the action is designed exactly for this transient-failure scenario.","Manually duplicating the action is error-prone, doesn''t respect the original failure/success branching cleanly, and reinvents what the built-in policy already provides.","Trigger concurrency controls how many flow RUNS execute in parallel; it has no effect on a single action''s retry behavior."]', 'medium', '["power-automate","error-handling"]', 0, 'https://learn.microsoft.com/power-automate/error-handling');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Automate', 'You need a flow to run automatically every day at 6:00 AM plant local time to generate a shift handover summary, independent of any record changes. Which trigger should you use?', '["Dataverse \"When a row is added\" trigger","Recurrence trigger scheduled daily at 6:00 AM with the correct time zone set","Manual \"Run a flow\" button trigger","HTTP request trigger"]', 1, 'The Recurrence trigger is specifically designed for time-based schedules independent of data changes, and supports setting the exact time and time zone needed for a daily 6:00 AM plant-local run.', '["A Dataverse row-creation trigger only fires when data changes occur, not on a fixed clock schedule.","Correct — Recurrence is the scheduled, time-based trigger built for this exact requirement.","A manual trigger requires a person to press a button; it does not run automatically every day.","An HTTP request trigger waits for an external call to invoke it; it is not a self-scheduling mechanism."]', 'easy', '["power-automate","triggers"]', 1, 'https://learn.microsoft.com/power-automate/triggers-introduction');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Pages', 'An external supplier portal built on Power Pages must let authenticated suppliers see ONLY their own company''s Purchase Orders, not those of other suppliers. What is the correct combination of configuration?', '["Disable anonymous access only","Table Permissions scoped to \"Contact\" (or a custom relationship-based rule) combined with Web Roles assigned to authenticated supplier users, plus column-level filtering via the relationship to the supplier account","A single Table Permission set to \"Global\" scope for Purchase Orders","Liquid template code only, with no Table Permissions"]', 1, 'Power Pages security relies on Web Roles (assigned to authenticated users) combined with Table Permissions whose scope (Contact, Account, Parent, or custom) restricts rows to those related to the logged-in user''s own account/contact — this is the only approach that enforces per-supplier row-level isolation.', '["Disabling anonymous access only ensures users must log in; it does not scope which rows an authenticated user can see.","Correct — scoped Table Permissions tied to the right relationship, assigned via Web Roles, is exactly how Power Pages enforces that suppliers see only their own data.","A \"Global\" scope grants access to ALL rows in the table for anyone with that permission, which leaks other suppliers'' purchase orders — the opposite of what''s required.","Liquid alone does not enforce server-side data security; Table Permissions are the actual enforcement layer, and omitting them leaves data exposed via the Web API regardless of what Liquid displays."]', 'hard', '["power-pages","table-permissions","security"]', 1, 'https://learn.microsoft.com/power-pages/security/table-permissions');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Pages', 'Which Power Pages feature lets you render dynamic, data-driven HTML content (e.g., looping through a filtered list of Defect records) directly inside a page template?', '["Liquid templates","Power BI embedded tiles only","Dataverse plug-ins","Model-driven app sitemaps"]', 0, 'Liquid is the templating language used throughout Power Pages to query Dataverse data (via tags like {% fetchxml %} or {% entities %}) and render dynamic HTML, including loops, conditionals, and filtering.', '["Correct — Liquid is the native templating/data-binding language for Power Pages content.","Power BI embedded tiles can show a report, but they are not a general mechanism for custom dynamic HTML loops over arbitrary Dataverse data.","Plug-ins run server-side business logic on Dataverse operations; they do not render page HTML.","Sitemaps are a model-driven app navigation concept, unrelated to Power Pages page content rendering."]', 'easy', '["power-pages","liquid"]', 0, 'https://learn.microsoft.com/power-pages/configure/liquid/liquid-overview');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Power Pages', 'You want suppliers on your Power Pages portal to authenticate using their own company''s Azure AD / Microsoft Entra ID tenant rather than creating local portal accounts. What should you configure?', '["Local authentication only with username/password","An external/federated identity provider using OpenID Connect (Entra ID as an external tenant) configured in the portal''s identity settings","Power Pages does not support external identity providers","A Power Automate flow to validate passwords"]', 1, 'Power Pages supports configuring external identity providers (including Microsoft Entra ID via OpenID Connect/SAML, or other providers) so external users authenticate with their own organizational credentials instead of local portal accounts.', '["Local authentication requires the supplier to create and manage a separate portal-specific account, which is not what''s being asked.","Correct — Power Pages explicitly supports federated/external identity providers like Entra ID via OpenID Connect for exactly this scenario.","This is factually incorrect — external identity provider federation is a supported, documented Power Pages capability.","Power Automate is not an authentication mechanism and cannot be used to validate login credentials for portal sign-in."]', 'medium', '["power-pages","authentication"]', 1, 'https://learn.microsoft.com/power-pages/security/authentication/azure-ad-b2c-provider');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Dataverse', 'What is the key functional difference between a "Choice" (Option Set) column and a "Choices" (Multi-select Option Set) column in Dataverse?', '["Choice stores text; Choices stores numbers","Choice allows selecting exactly one option; Choices allows selecting multiple options from the same list, stored as a collection","There is no difference, they are the same type","Choices can only be used in Canvas Apps, not model-driven apps"]', 1, 'A Choice (Option Set) column allows a single selected value from a predefined list, while a Choices (Multi-select Option Set) column allows multiple values to be selected and stored together for the same row.', '["Both are backed by underlying integer values mapped to labels — the distinguishing factor is cardinality (single vs multiple selection), not storage data type.","Correct — single-select vs multi-select is the defining functional difference.","They are distinct column types with different selection behavior and different data shapes when queried.","Multi-select option sets are fully supported in both canvas and model-driven apps."]', 'easy', '["dataverse","columns","choice"]', 0, 'https://learn.microsoft.com/power-apps/maker/data-platform/create-edit-choices-column');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL200', 'Model-Driven Apps', 'An editable grid on a model-driven app view is being used to let Quality Inspectors bulk-update the "Status" column for many Defect records at once without opening each record. Which feature are they using?', '["Quick Create Form","Editable Grid control on the view","Business Process Flow","Dashboard interactive filter"]', 1, 'The Editable Grid control, when enabled on a view, allows inline editing of column values for multiple records directly within the grid, without opening each record form individually.', '["Quick Create Forms are for creating one new record quickly in a panel, not bulk-editing an existing list.","Correct — the Editable Grid control is specifically built for in-place, multi-record inline editing.","Business Process Flows guide a single record through stages; they are unrelated to grid-based bulk editing.","Dashboard interactive filtering cross-filters charts/lists by selection; it does not provide inline editing of field values."]', 'easy', '["model-driven-apps","editable-grid"]', 1, 'https://learn.microsoft.com/power-apps/user/use-editable-grids');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Preparation', 'You are using Power Query to combine monthly inspection CSV files from a folder, where each file has identical column headers. Which transformation most efficiently combines all files into a single table?', '["Merge Queries","Append Queries (or \"Combine Files\" from a folder connector)","Group By","Pivot Column"]', 1, 'Append Queries stacks rows from multiple tables with the same schema into one table. The Folder connector''s "Combine Files" feature automates this for every file in a folder, which is exactly suited for repeated identical-schema CSV exports.', '["Merge Queries joins tables side-by-side on matching keys (like a SQL join), adding columns — it does not stack rows from multiple files.","Correct — Append (and Combine Files for folders) stacks rows from multiple same-shape tables into one.","Group By aggregates existing rows into summarized groups; it does not combine separate source files.","Pivot Column reshapes rows into columns; it is unrelated to combining multiple files."]', 'easy', '["power-query","append","data-prep"]', 1, 'https://learn.microsoft.com/power-query/append-queries');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Preparation', 'A column "OrderDate" was imported as text in the format "2024-03-15" from a legacy MES system. Which M function/step correctly and reliably converts it to a true Date type?', '["Text.Upper()","Table.TransformColumnTypes(Source, {{\"OrderDate\", type date}})","Number.FromText()","Table.RenameColumns()"]', 1, 'Table.TransformColumnTypes with a target type of "type date" (generated by the Change Type UI) explicitly parses the text into a proper Date data type, enabling correct sorting, filtering, and DAX time-intelligence functions downstream.', '["Text.Upper() only changes text casing; it has no effect on data type.","Correct — this is the standard M function the Power Query UI generates when you set a column''s type to Date.","Number.FromText() converts to a numeric type, not a date type — wrong target type entirely.","Table.RenameColumns() only changes a column''s name, not its data type or values."]', 'easy', '["power-query","data-types"]', 1, 'https://learn.microsoft.com/power-query/data-types');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Preparation', 'You need to extract only the numeric defect code from a text column where values look like "DEF-00234-A". What Power Query feature is most appropriate for a repeatable, UI-driven solution?', '["Manually type a custom M function from scratch with no UI assistance","Extract > Text Between Delimiters, or Column From Examples","Replace Values on the whole column","Remove Duplicates"]', 1, '"Extract > Text Between Delimiters" (splitting on "-") or "Column From Examples" (where you type sample outputs and Power Query infers the transformation) are both UI-driven, repeatable ways to pull substrings like the numeric code out of a structured text pattern.', '["While a fully custom M function could work, it is not the most appropriate or efficient approach when built-in, repeatable UI transformations exist for this exact pattern.","Correct — these UI features are purpose-built for extracting substrings from structured text patterns.","Replace Values swaps exact matching values; it cannot dynamically extract a variable substring from each row.","Remove Duplicates eliminates repeated rows; it has nothing to do with extracting substrings."]', 'medium', '["power-query","text-transformation"]', 1, 'https://learn.microsoft.com/power-query/add-column-from-example');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Preparation', 'A dataflow refresh is failing intermittently because a source API occasionally returns an unexpected null in a required field, breaking downstream type conversion. What is the best practice to make the query resilient?', '["Delete the dataflow and rebuild it from scratch each time it fails","Add error-handling steps such as \"Replace Errors\" or conditional logic (e.g., try...otherwise) around the type conversion step","Ignore the error, it will resolve itself","Switch the dataset from Import to DirectQuery, which has no refresh errors"]', 1, 'Power Query''s try...otherwise expression (and the UI equivalents "Replace Errors" / "Remove Errors") let you catch row-level errors and substitute a default value or null gracefully, instead of failing the whole refresh.', '["Rebuilding from scratch does not address the root cause and is not a sustainable or recommended practice.","Correct — try...otherwise / Replace Errors is the standard resilient-query pattern for handling unpredictable source data issues.","Ignoring errors does not make them self-resolve; the refresh will continue to fail.","DirectQuery mode queries the source live and can still surface errors from bad data; switching storage mode does not inherently fix a data quality/type conversion issue."]', 'medium', '["power-query","error-handling","dataflows"]', 0, 'https://learn.microsoft.com/power-query/dealing-with-errors');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Preparation', 'Which Power Query feature should be used to centralize and reuse a cleaned, transformed "Plants" dimension table across multiple Power BI datasets owned by different report authors in the same workspace?', '["Copy and paste the Power Query M code into each report","A certified Dataflow (Power BI dataflow) referenced from each dataset","A local Excel file shared via email","Table.Buffer() applied in each report individually"]', 1, 'Power BI Dataflows store reusable, centrally-governed ETL logic and output data (to Dataverse or Azure Data Lake) that multiple datasets can reference as a source, avoiding duplicated transformation logic and ensuring one source of truth.', '["Copy-pasting M code creates duplicated, drifting logic that must be manually kept in sync across reports.","Correct — Dataflows are the governed, reusable ETL layer designed for sharing transformation logic/output across multiple datasets.","Emailing an Excel file is a manual, ungoverned, and non-scalable approach, and loses lineage/refresh automation.","Table.Buffer() caches a table in memory during a single query''s evaluation for performance; it does not enable sharing data across different datasets/reports."]', 'medium', '["dataflows","governance"]', 1, 'https://learn.microsoft.com/power-query/dataflows/dataflows-introduction-self-service');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Modeling', 'In a star schema, a "Date" dimension table is related to a "Sales" fact table. What should the cardinality and cross-filter direction typically be for this relationship?', '["Many-to-many, Both directions","One (Date) to Many (Sales), Single direction (filters flow from Date to Sales)","Many (Date) to One (Sales), Single direction","One-to-one, Both directions"]', 1, 'A well-formed Date dimension has one row per date (unique), while the Sales fact table has many rows per date — making it a one-to-many relationship, with filters flowing from the "one" side (Date) to the "many" side (Sales); single-direction filtering is the recommended default for star schemas.', '["Many-to-many relationships are used when neither side has a unique key for the relationship column — not appropriate for a clean Date dimension, and bidirectional filtering on a fact table risks ambiguous filter propagation and performance issues.","Correct — this is the textbook star-schema pattern: one Date row relates to many Sales rows, filtering one-way from dimension to fact.","This reverses the actual cardinality — Date is the \"one\" side, not Sales.","One-to-one would mean each Date row matches exactly one Sales row, which is not true for a fact table with many transactions per day."]', 'medium', '["data-modeling","star-schema","cardinality"]', 1, 'https://learn.microsoft.com/power-bi/guidance/star-schema');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Modeling', 'Two fact tables, "Sales" and "Returns," both need to filter by the same "Date" and "Product" dimensions. What is the recommended modeling approach to avoid duplicating dimension tables and enable consistent slicing across both facts?', '["Create a separate Date and Product table for each fact table","Use a single shared Date dimension and single shared Product dimension, each related to both fact tables (conformed dimensions)","Merge Sales and Returns into one fact table regardless of grain differences","Use bidirectional relationships from Sales to Returns directly"]', 1, 'Conformed dimensions — a single Date table and single Product table shared by multiple fact tables — are the standard star/galaxy schema pattern, ensuring consistent filtering and avoiding duplicated maintenance.', '["Duplicating dimension tables per fact table creates maintenance overhead and risks inconsistent filtering/labels between the two.","Correct — conformed (shared) dimensions connected to multiple fact tables is the standard, scalable modeling pattern.","Merging fact tables of different grain (e.g., different transaction types/measures) can distort aggregations and is not the recommended fix for this requirement.","A direct relationship between two fact tables is not the standard approach; facts should relate to shared dimensions, not to each other directly."]', 'hard', '["data-modeling","conformed-dimensions"]', 1, 'https://learn.microsoft.com/power-bi/guidance/star-schema');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Modeling', 'You have a "Shift" dimension with values Morning/Afternoon/Night that does not change over time and has no natural source table — it only exists to label data. What is the best way to create it in the model?', '["Import it from a CSV file maintained externally","A calculated table using DAX, e.g. DATATABLE() or a UNION of ROW() literals","A Power Automate flow that writes to Dataverse","A Many-to-many relationship with no table"]', 1, 'For small, static, manually-defined lookup/dimension tables with no natural source, a DAX calculated table (using functions like DATATABLE, or UNION of ROW()) is the standard lightweight approach, avoiding unnecessary external dependencies.', '["Maintaining a separate CSV file for 3 static values adds unnecessary external dependency and refresh overhead.","Correct — a small DAX calculated table is the right-sized tool for a tiny, static, manually-defined dimension.","A Power Automate flow writing to Dataverse is a heavy, overengineered solution for 3 static label values in a Power BI model.","A relationship cannot exist \"with no table\" — this option is not a coherent modeling technique."]', 'medium', '["data-modeling","calculated-tables","dax"]', 1, 'https://learn.microsoft.com/dax/datatable-function-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Modeling', 'A "Machine" dimension table has a self-referencing hierarchy where each machine has a "ParentMachineID" representing a sub-assembly relationship. Which Power BI/DAX feature is designed to model and navigate this kind of hierarchy?', '["A standard one-to-many relationship only","Parent-Child hierarchy functions (PATH, PATHITEM, PATHLENGTH) to flatten the hierarchy into levels","Row-level security roles","A calculated column using CONCATENATE only"]', 1, 'DAX provides PATH() and related functions (PATHITEM, PATHLENGTH, PATHCONTAINS) specifically to flatten a self-referencing parent-child structure into a usable hierarchy with discrete levels for slicing and drill-down.', '["A plain relationship cannot be self-referencing in a way that flattens into navigable hierarchy levels on its own — it needs the PATH-based pattern.","Correct — PATH()-based functions are the documented, purpose-built technique for parent-child hierarchies in DAX.","Row-level security governs data access per user; it has nothing to do with modeling a hierarchy structure.","CONCATENATE alone does not create a navigable multi-level hierarchy; it just joins text strings."]', 'hard', '["data-modeling","parent-child","dax"]', 1, 'https://learn.microsoft.com/dax/understanding-functions-for-parent-child-hierarchies-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Modeling', 'What is the primary performance benefit of using Import mode with a well-optimized star schema versus DirectQuery for a large historical fact table in Power BI?', '["Import mode always shows real-time data with zero latency","Import mode compresses data into VertiPaq''s in-memory columnar store, enabling very fast aggregations without hitting the source system per query","DirectQuery always outperforms Import for any dataset size","There is no performance difference between the two modes"]', 1, 'Import mode loads data into Power BI''s VertiPaq in-memory columnar engine, which is highly compressed and optimized for fast aggregation queries, independent of the source system''s live performance — this is generally much faster than DirectQuery, which must translate every visual interaction into a live query against the source.', '["Import mode is a periodic snapshot (refreshed on a schedule); it is DirectQuery that reflects real-time source data, not Import.","Correct — VertiPaq''s compressed columnar in-memory storage is the core reason Import mode is typically much faster for aggregation-heavy analytics.","This is generally the opposite of reality for aggregation-heavy analytical queries — DirectQuery performance depends entirely on the source system and network latency.","There is a well-documented, significant performance difference, which is exactly why mode choice is a key PL-300 exam topic."]', 'medium', '["data-modeling","storage-mode","performance"]', 0, 'https://learn.microsoft.com/power-bi/connect-data/service-dataset-modes-understand');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'Which DAX measure correctly calculates "Total Sales for the West region only," regardless of what region slicer selection is currently applied elsewhere in the report?', '["SUM(Sales[Amount])","CALCULATE(SUM(Sales[Amount]), Sales[Region] = \"West\")","SUMX(Sales, Sales[Amount])","Sales[Amount] + Sales[Region]"]', 1, 'CALCULATE modifies the filter context before evaluating its expression; adding Sales[Region] = "West" as a filter argument forces the calculation to always consider only West region rows, overriding other filters applied to Region in the report (since CALCULATE filters replace existing filters on the same column).', '["Plain SUM(Sales[Amount]) respects whatever filter context is already active (e.g., current slicer selections) — it does not force \"West only.\"","Correct — CALCULATE with an explicit Region filter guarantees the West-only result regardless of external report filters on Region.","SUMX iterates row-by-row to sum an expression, but by itself it still respects the ambient filter context — it does not force West only, and is unnecessary here since no row-by-row calculation is needed.","This is not valid/meaningful DAX — you cannot add a numeric column and a text column together."]', 'medium', '["dax","calculate","filter-context"]', 1, 'https://learn.microsoft.com/dax/calculate-function-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'What does the following measure calculate? `Avg Defect Cost := SUMX(Defects, Defects[Quantity] * Defects[UnitCost]) / SUM(Defects[Quantity])`', '["The simple average of the UnitCost column, ignoring quantity","The weighted average cost per unit, accounting for quantity at each row","The total cost of all defects","The count of defect records"]', 1, 'SUMX multiplies Quantity by UnitCost for each row and sums the results (total cost), then divides by total Quantity — this produces a quantity-weighted average unit cost, which differs from a simple unweighted AVERAGE(UnitCost).', '["A simple average would be AVERAGE(Defects[UnitCost]); this formula explicitly weights by Quantity via the row-by-row multiplication in SUMX.","Correct — dividing total weighted cost by total quantity yields the quantity-weighted average cost per unit.","The numerator alone (SUMX part) is total cost, but the full expression divides by quantity, producing an average, not a total.","Nothing in this formula counts rows; COUNTROWS would be needed for that."]', 'hard', '["dax","sumx","weighted-average"]', 1, 'https://learn.microsoft.com/dax/sumx-function-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'You need a measure showing Sales for the same period last year, so it can be compared side-by-side with current Sales on a line chart. Assuming a proper Date table marked as the date table, which formula is correct?', '["Prior Year Sales := SUM(Sales[Amount]) - 1","Prior Year Sales := CALCULATE(SUM(Sales[Amount]), SAMEPERIODLASTYEAR(''Date''[Date]))","Prior Year Sales := SUM(Sales[Amount]) / 365","Prior Year Sales := Sales[Amount] - Sales[Amount]"]', 1, 'SAMEPERIODLASTYEAR shifts the current date filter context back exactly one year, and wrapping it as a CALCULATE filter argument around SUM(Sales[Amount]) is the canonical DAX time-intelligence pattern for year-over-year comparisons.', '["Subtracting 1 from a dollar total is not a meaningful or correct time-shift operation.","Correct — this is the standard, documented DAX time-intelligence pattern for \"same period last year.\"","Dividing by 365 assumes an unrelated daily-average interpretation and does not shift the date context to the prior year at all.","This literally evaluates to zero for every row/context; it has no time-intelligence meaning."]', 'medium', '["dax","time-intelligence"]', 0, 'https://learn.microsoft.com/dax/sameperiodlastyear-function-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'A measure `Open Rate := DIVIDE(COUNTROWS(FILTER(Defects, Defects[Status] = "Open")), COUNTROWS(Defects))` is returning a blank instead of an error when there are zero total defect rows in the current filter context. Why?', '["DIVIDE() always returns blank regardless of inputs","DIVIDE() has a built-in safeguard: when the denominator is 0 (or blank), it returns a specified alternate result, or BLANK() by default, instead of throwing a divide-by-zero error","FILTER() silently fails with zero rows","COUNTROWS() cannot return 0"]', 1, 'DIVIDE(numerator, denominator, [alternateResult]) is the recommended safe-division function in DAX precisely because it gracefully handles division by zero/blank denominators — returning the optional alternateResult if provided, or BLANK() if omitted — avoiding the "#DIV/0" style error that the plain "/" operator would surface.', '["DIVIDE() returns the actual computed result normally; it only falls back to blank/alternate specifically when the denominator is zero or blank.","Correct — this built-in safe-division behavior is exactly why no error appears.","FILTER() works correctly and simply returns an empty table when no rows match; it does not \"fail.\"","COUNTROWS() can absolutely return 0 when a table (or filtered table) has no rows — that is expected, valid behavior, not a limitation."]', 'medium', '["dax","divide","error-handling"]', 1, 'https://learn.microsoft.com/dax/divide-function-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'Which DAX concept describes the fact that a measure''s result can change automatically depending on which rows are visible due to slicers, filters, or the position of a cell in a matrix — without changing the measure''s formula?', '["Row context","Filter context","Query folding","Data lineage"]', 1, 'Filter context is the set of filters (from slicers, visual filters, cross-highlighting, matrix row/column headers, and CALCULATE modifiers) currently applied when a measure is evaluated — it is why the same measure formula can produce different results in different visual cells.', '["Row context refers to the \"current row\" during row-by-row iteration (e.g., inside SUMX or a calculated column), which is a related but distinct concept from the ambient filter environment described here.","Correct — filter context is precisely the mechanism that causes a measure to recalculate differently per cell/visual based on active filters.","Query folding is a Power Query (M) concept about pushing transformation steps back to the data source; it is unrelated to DAX evaluation context.","Data lineage refers to tracking where data came from and how it was transformed, not runtime filter behavior."]', 'medium', '["dax","filter-context"]', 0, 'https://learn.microsoft.com/dax/context-in-dax-formulas');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'What is the purpose of using a DAX variable with VAR and RETURN, as in `VAR TotalDefects = COUNTROWS(Defects) RETURN IF(TotalDefects = 0, BLANK(), TotalDefects)`?', '["Variables change the filter context of the report","Variables improve readability and performance by computing an expression once and reusing it, rather than re-evaluating it multiple times","Variables are required syntax for every DAX measure","Variables can only store text strings"]', 1, 'VAR...RETURN lets you name and compute an intermediate expression a single time, then reference it multiple times in the RETURN expression — improving both formula readability and performance by avoiding redundant recalculation.', '["Variables do not alter filter context by themselves; they simply store the result of an expression evaluated within the current context at the point of definition.","Correct — this is exactly the readability and performance benefit variables provide.","VAR/RETURN is optional syntax; plenty of valid DAX measures are written without variables.","Variables can store any DAX expression result — numbers, text, tables, booleans — not just text."]', 'easy', '["dax","variables"]', 0, 'https://learn.microsoft.com/dax/support-for-variables-in-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'Fix the broken measure. Intended behavior: total Sales Amount only for rows where Quantity is greater than 10. Broken formula: `CALCULATE(SUM(Sales[Amount]), FILTER(Sales[Quantity] > 10))`. What is wrong and how should it be fixed?', '["Nothing is wrong, it works as written","FILTER() requires a table as its first argument, not just a boolean condition — it should be FILTER(Sales, Sales[Quantity] > 10), or more simply just CALCULATE(SUM(Sales[Amount]), Sales[Quantity] > 10)","CALCULATE cannot accept FILTER as an argument","SUM should be replaced with SUMX"]', 1, 'FILTER() always takes a table as its first argument and a boolean expression as its second (FILTER(<table>, <condition>)). The broken formula omits the table, which is a syntax error. The simplest fix for a single-column condition is to skip FILTER entirely and pass the boolean filter directly to CALCULATE.', '["The formula as written is syntactically invalid — FILTER is missing its required table argument.","Correct — FILTER needs an explicit table argument, and for a simple single-column condition like this, passing the boolean expression directly to CALCULATE is both valid and simpler.","CALCULATE frequently takes FILTER() as a filter argument — that combination is valid DAX; the issue is solely FILTER''s missing table argument.","SUMX is unnecessary here; the problem is not with the aggregation function but with the malformed FILTER call."]', 'hard', '["dax","debugging","filter"]', 1, 'https://learn.microsoft.com/dax/filter-function-dax');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Visualizations', 'You want users to click a bar in a "Defects by Plant" chart and have a "Defect Trend" line chart on the SAME page update to show only that plant''s trend, without navigating to another page. What report feature enables this default behavior?', '["Bookmarks","Cross-filtering/cross-highlighting between visuals on the same page (default interaction)","Drillthrough pages","Q&A visual"]', 1, 'By default, selecting a data point in one visual cross-filters (or cross-highlights) other visuals on the same report page that share a related field — exactly matching this same-page, click-to-filter behavior.', '["Bookmarks capture and restore a specific state (filters, visibility, slicer selections) for later recall via a button; they are not the mechanism for default click-based cross-filtering between visuals.","Correct — this default visual interaction (cross-filter/cross-highlight) is exactly what''s being described.","Drillthrough navigates to a SEPARATE detail page filtered by the clicked value — the requirement explicitly says the update should happen on the same page.","The Q&A visual answers natural-language questions typed by the user; it is unrelated to clicking a bar to filter other visuals."]', 'easy', '["visualizations","interactions"]', 1, 'https://learn.microsoft.com/power-bi/create-reports/service-reports-visual-interactions');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Visualizations', 'You need a button that, when clicked, resets all slicers on the page back to their default (no filter) state. What should you create?', '["A Bookmark capturing the default/unfiltered state, applied via a button''s \"Action\" set to that bookmark","A Drillthrough page","A calculated column","A Q&A visual"]', 0, 'Creating a bookmark while all slicers are in their default/cleared state, then assigning a button''s Action type to "Bookmark" pointing to that bookmark, is the standard way to build a "Reset Filters" button.', '["Correct — a bookmark capturing the cleared slicer state, triggered by a button, is the documented pattern for reset-filter buttons.","Drillthrough pages navigate to a different filtered page; they do not reset slicers on the current page.","A calculated column computes a static value per row at refresh time; it has no interactive button behavior.","The Q&A visual is for natural-language querying, unrelated to resetting slicer states."]', 'medium', '["visualizations","bookmarks"]', 0, 'https://learn.microsoft.com/power-bi/create-reports/desktop-bookmarks');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Visualizations', 'A plant manager wants to click on a specific "Machine" row in a summary table and navigate to a dedicated detail page showing only that machine''s full maintenance history, with a back button to return. What feature should you implement?', '["Cross-highlighting only","Drillthrough page with a \"back\" navigation button","Export to Excel","Conditional formatting"]', 1, 'Drillthrough pages are designed specifically for this: right-click (or Ctrl+click) a data point to navigate to a separate detail page pre-filtered to that context, and a Back button (auto-added or manually configured) returns to the originating page.', '["Cross-highlighting changes visuals on the SAME page; it does not navigate to a separate dedicated detail page.","Correct — drillthrough is exactly the documented feature for navigating to a filtered detail page with a way back.","Export to Excel extracts data out of Power BI; it is not a navigation/detail-page feature.","Conditional formatting changes visual styling (colors/icons) based on values; it has nothing to do with page navigation."]', 'easy', '["visualizations","drillthrough"]', 1, 'https://learn.microsoft.com/power-bi/create-reports/desktop-drillthrough');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Visualizations', 'Which accessibility best practice should you follow when designing a Power BI report that will be used by colorblind plant floor supervisors to identify "Critical" vs "Normal" defect statuses?', '["Rely exclusively on red vs. green coloring with no other visual cue","Combine color with a secondary visual cue, such as icons, shapes, or text labels, and choose a colorblind-safe palette","Use the smallest possible font size to fit more data","Remove all alt text from visuals to keep the report \"clean\""]', 1, 'Accessible report design principles recommend never relying on color alone to convey meaning — pairing color with icons, patterns, or text labels, and selecting colorblind-safe palettes, ensures the information is understandable regardless of color perception.', '["Red/green-only encoding is one of the most common accessibility failures, especially for red-green colorblindness (the most prevalent type).","Correct — combining color with a non-color cue, using accessible palettes, is the recommended best practice.","Small font size actively harms readability and accessibility for all users, especially those with visual impairments.","Alt text is essential for screen reader users; removing it harms accessibility rather than helping it."]', 'medium', '["visualizations","accessibility"]', 1, 'https://learn.microsoft.com/power-bi/create-reports/desktop-accessibility-creating-reports');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Visualizations', 'A report has 12 KPI cards and 3 charts on one page, and plant floor users report it feels cluttered and slow to scan on a shop-floor display. What design principle should you apply first?', '["Add more cards to provide additional context","Apply visual hierarchy and decluttering: prioritize the 3-5 most critical KPIs, use consistent alignment/whitespace, and move secondary detail to a drill-through or tooltip","Switch every visual to 3D charts for visual interest","Increase the page refresh rate to once per second"]', 1, 'Good dashboard design emphasizes a clear visual hierarchy: a small number of the most important KPIs prominently placed, consistent alignment and whitespace, and secondary/detail information pushed to drillthrough or tooltips — reducing cognitive load for a quick-scan environment like a shop floor.', '["Adding more cards would worsen clutter, not reduce it.","Correct — reducing to the most critical KPIs and improving layout hierarchy directly addresses the clutter and scanability complaint.","3D charts are explicitly discouraged in BI design guidance — they distort value perception and are harder to read quickly.","Refresh rate affects data freshness, not visual clutter or layout; it would also unnecessarily strain the data source."]', 'medium', '["visualizations","design-principles"]', 1, 'https://learn.microsoft.com/power-bi/guidance/report-design-tips-tricks-report-builder');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Governance & RLS', 'You need to ensure that a Plant Manager logged into a Power BI report only ever sees rows for their own PlantID, dynamically, without creating a separate report per plant. What feature should you implement?', '["Separate .pbix files per plant, published individually","Dynamic Row-Level Security (RLS) using a DAX rule referencing USERPRINCIPALNAME() mapped to a Plant/User security table","Power BI workspace permissions only","Static RLS with one hardcoded role per plant, manually assigned per user in the service"]', 1, 'Dynamic RLS defines a single DAX filter rule (commonly using USERPRINCIPALNAME() or USERNAME() joined to a mapping table of Plant-to-User) so the same report automatically filters data based on who is logged in — one report, no per-plant duplication, scales automatically as users/plants are added.', '["Separate files per plant multiply maintenance effort and do not scale; this is explicitly what RLS is designed to avoid.","Correct — dynamic RLS with a USERPRINCIPALNAME()-based mapping table is the standard, scalable solution for \"each user sees only their own data\" in one shared report.","Workspace permissions control who can access/edit the workspace/report as a whole, not row-level data filtering within the report.","Static RLS (hardcoded roles per plant) works but requires manually creating and assigning a role per plant and re-assigning users individually — it does not scale as cleanly as dynamic RLS when there are many plants/users, which this question is testing you to recognize."]', 'hard', '["rls","governance","security"]', 1, 'https://learn.microsoft.com/power-bi/enterprise/service-admin-rls');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Governance & RLS', 'What is the key difference between a Power BI "Workspace" and a Power BI "App"?', '["They are identical concepts with different names","A workspace is the collaborative backstage area where content is built/edited; an App is a curated, read-optimized, published front-end distributed to broader consumers","An App is only available in Power BI Desktop","A workspace can only contain one report, while an App can contain many"]', 1, 'Workspaces are where creators collaborate on and manage reports, dashboards, datasets, and dataflows. Apps are a packaged, polished, read-only distribution mechanism built FROM a workspace''s content, typically given to a wider audience of business consumers with simpler navigation.', '["They serve clearly distinct purposes — authoring/collaboration (workspace) versus curated distribution (app) — and are not interchangeable.","Correct — this creator-vs-consumer-facing distinction is exactly the relationship between workspaces and apps.","Apps are consumed in the Power BI Service (web/mobile), not Power BI Desktop, which is the authoring tool.","Both workspaces and apps can contain many reports/dashboards; the limitation described is not accurate."]', 'easy', '["governance","workspaces","apps"]', 0, 'https://learn.microsoft.com/power-bi/consumer/end-user-apps');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Governance & RLS', 'A dataset containing plant-wide salary and HR data must never be shared outside the organization, even if a report built on it is accidentally shared via a public link. What governance control best enforces this organization-wide?', '["A strongly worded note in the report description","A Sensitivity Label (via Microsoft Purview Information Protection) applied to the dataset/report enforcing encryption and sharing restrictions","Renaming the dataset to include \"Confidential\"","Setting the report''s color theme to red"]', 1, 'Sensitivity labels (integrated with Microsoft Purview Information Protection) can be applied to Power BI content to enforce actual technical protections — such as blocking external sharing or applying encryption — not just a visual or descriptive cue.', '["A text note is not an enforced technical control; users can ignore it or share anyway.","Correct — sensitivity labels provide enforceable, organization-wide protection policies, including restricting external sharing.","Renaming is cosmetic and has zero effect on actual data protection or sharing capability.","Visual styling (color themes) has no bearing on data security or sharing controls."]', 'medium', '["governance","sensitivity-labels"]', 0, 'https://learn.microsoft.com/power-bi/enterprise/service-security-sensitivity-label-overview');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Governance & RLS', 'A Power BI dataset in Import mode needs to stay current with the source database throughout the business day. What should you configure to keep it reasonably fresh without manual intervention?', '["Scheduled Refresh (e.g., every few hours, up to the plan''s maximum daily refreshes) via a configured gateway if the source is on-premises","Export the report to PDF daily","Switch every visual to a live connection with no dataset","Manually click \"Refresh\" in Power BI Desktop and republish each day"]', 0, 'Scheduled Refresh, configured in the dataset settings (and requiring an On-premises Data Gateway if the source is not cloud-accessible), automatically re-imports data at defined intervals throughout the day without manual effort.', '["Correct — Scheduled Refresh (with a gateway for on-prem sources) is the standard automated mechanism for keeping Import-mode data current.","Exporting to PDF creates a static snapshot file; it does not refresh the underlying dataset at all.","Switching to live connection/DirectQuery changes the storage mode entirely (a different architecture decision with its own trade-offs) rather than simply scheduling refresh for an existing Import-mode dataset.","Manual refresh and republishing is labor-intensive, error-prone, and explicitly what Scheduled Refresh is meant to automate away."]', 'easy', '["governance","refresh"]', 1, 'https://learn.microsoft.com/power-bi/connect-data/refresh-data');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Governance & RLS', 'You need to validate that your dynamic RLS rule correctly restricts data before publishing to the service. What Power BI Desktop feature lets you preview the report exactly as a specific role/user would see it, without actually publishing or logging in as that user?', '["Performance Analyzer","\"View As Roles\" in the Modeling tab","Publish to web","Query Diagnostics"]', 1, '"View As Roles" (Modeling ribbon) lets a report author preview the model/report as if a specific RLS role (optionally impersonating a specific username) were applied, entirely within Desktop, before publishing — the standard way to validate RLS rules.', '["Performance Analyzer measures visual/query render times; it has nothing to do with simulating RLS roles.","Correct — \"View As Roles\" is specifically built for previewing RLS-filtered results before publishing.","\"Publish to web\" creates a public, unsecured embed link — the opposite of testing restricted, secure RLS behavior, and is explicitly discouraged for sensitive data.","Query Diagnostics traces Power Query step-by-step execution/timing; it is unrelated to RLS role simulation."]', 'medium', '["rls","testing"]', 0, 'https://learn.microsoft.com/power-bi/enterprise/service-admin-rls#use-view-as-role-to-test-your-rls-rules');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Preparation', 'A Power Query step named "Filtered Rows" is taking an unusually long time against a large SQL Server source table. What should you check first to diagnose whether the query is being executed efficiently?', '["Whether the step''s operation can be \"query folded\" back to the SQL source (so filtering happens in SQL Server, not after pulling all rows into Power BI)","The color scheme of the Power Query editor","The number of visuals on the report page","The report''s file name"]', 0, 'Query folding pushes supported transformation steps down to be executed by the source system (e.g., translated into a SQL WHERE clause) instead of pulling all rows into Power BI''s engine first and filtering locally — folding dramatically improves performance for large relational sources, and its absence is the most common root cause of slow refreshes like this.', '["Correct — checking whether the step still folds (visible via \"View Native Query\" availability) is the right first diagnostic step for slow source-side transformations.","The editor''s color scheme has no effect on query execution performance.","The number of visuals on a report page affects rendering, not Power Query refresh/transformation performance.","The file name has no bearing on query execution performance."]', 'hard', '["power-query","query-folding","performance"]', 0, 'https://learn.microsoft.com/power-query/query-folding-basics');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'Data Modeling', 'What is the main risk of leaving a bidirectional (both-direction) cross-filter relationship enabled between two large fact tables in a complex model with many relationships?', '["It has no risk and is always recommended for every relationship","It can introduce ambiguous filter propagation paths and circular dependencies, and can noticeably degrade query performance","It automatically encrypts the data","It disables DAX measures entirely"]', 1, 'Bidirectional filtering allows filters to flow both ways, which in models with multiple relationship paths can create ambiguous or circular filter propagation, confusing results, and added query engine overhead evaluating more filter paths — this is why single-direction filtering is the recommended default, with bidirectional used sparingly and intentionally.', '["Bidirectional filtering is a deliberate, situational tool, not a universal best practice — overusing it is a well-documented anti-pattern.","Correct — ambiguous propagation paths and performance degradation are the documented risks of overusing bidirectional filtering.","Cross-filter direction has nothing to do with data encryption.","DAX measures continue to function; they may just return unexpected results due to the altered filter propagation, not fail entirely."]', 'hard', '["data-modeling","bidirectional-filtering"]', 0, 'https://learn.microsoft.com/power-bi/transform-model/desktop-many-to-many-relationships');
    INSERT INTO questions (track, domain, question_text, options, correct_index, explanation, why_wrong, difficulty, tags, is_gemba, doc_link) VALUES ('PL300', 'DAX', 'Which function would you use inside a measure to return the number of DISTINCT machine IDs that logged at least one defect, from a Defects fact table?', '["COUNT(Defects[MachineID])","DISTINCTCOUNT(Defects[MachineID])","SUM(Defects[MachineID])","COUNTROWS(Defects)"]', 1, 'DISTINCTCOUNT counts the number of unique (non-duplicate) values in a column — exactly what''s needed to count how many distinct machines appear in the Defects table, regardless of how many defect rows each machine has.', '["COUNT() counts non-blank values INCLUDING duplicates, so a machine with 5 defects would be counted 5 times, not once.","Correct — DISTINCTCOUNT is the purpose-built function for counting unique values in a column.","SUM() would add up MachineID numeric values arithmetically, which is meaningless for an ID field.","COUNTROWS(Defects) counts total defect rows, not distinct machines — a single machine with multiple defects would inflate this count."]', 'easy', '["dax","distinctcount"]', 1, 'https://learn.microsoft.com/dax/distinctcount-function-dax');
    -- challenges
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL300', 'dax', 'CALCULATE: Region-Locked Total', 'Write a DAX measure that returns the Total Amount from the Sales table for the "West" region ONLY — regardless of any other filters that might be active in a report. Use CALCULATE with a filter argument on Sales[Region].', 'CALCULATE(SUM(Sales[Amount]), /* add your Region filter here */)', '{"primaryTable":"Sales","rows":[{"Region":"West","Amount":1200},{"Region":"East","Amount":800},{"Region":"West","Amount":950},{"Region":"North","Amount":400},{"Region":"West","Amount":300}]}', '2450', 'CALCULATE filter arguments look like Table[Column] = "Value". Equality in DAX uses a single "=".', 'CALCULATE(SUM(Sales[Amount]), Sales[Region] = "West")', 'easy');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL300', 'dax', 'SUMX: Row-by-Row Revenue', 'The OrderLines table has Qty and Price columns but no pre-computed line total. Write a measure using SUMX that multiplies Qty by Price for each row and sums the results.', 'SUMX(OrderLines, /* your row expression here */)', '{"primaryTable":"OrderLines","rows":[{"Product":"Bolt","Qty":10,"Price":2.5},{"Product":"Nut","Qty":20,"Price":1.25},{"Product":"Washer","Qty":50,"Price":0.5}]}', '75', 'SUMX(<table>, <expression evaluated per row>). Reference columns as OrderLines[Qty] and OrderLines[Price] inside the row expression.', 'SUMX(OrderLines, OrderLines[Qty] * OrderLines[Price])', 'medium');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL300', 'dax', 'FILTER + COUNTROWS: Open Work Orders', 'Count how many WorkOrders rows have Status = "Open" using FILTER nested inside COUNTROWS.', 'COUNTROWS(FILTER(WorkOrders, /* condition */))', '{"primaryTable":"WorkOrders","rows":[{"WOID":1,"Status":"Open"},{"WOID":2,"Status":"Closed"},{"WOID":3,"Status":"Open"},{"WOID":4,"Status":"Open"},{"WOID":5,"Status":"Closed"}]}', '3', 'FILTER always needs a table as its first argument: FILTER(WorkOrders, WorkOrders[Status] = "Open").', 'COUNTROWS(FILTER(WorkOrders, WorkOrders[Status] = "Open"))', 'medium');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL300', 'dax', 'DIVIDE: Safe Critical Defect Rate', 'Calculate the proportion of Defects rows where Severity = "Critical", using DIVIDE so it never throws a divide-by-zero error even if Defects is empty.', 'DIVIDE(COUNTROWS(FILTER(Defects, /* condition */)), COUNTROWS(Defects))', '{"primaryTable":"Defects","rows":[{"DefectID":1,"Severity":"Critical"},{"DefectID":2,"Severity":"Minor"},{"DefectID":3,"Severity":"Critical"},{"DefectID":4,"Severity":"Minor"},{"DefectID":5,"Severity":"Minor"},{"DefectID":6,"Severity":"Critical"},{"DefectID":7,"Severity":"Minor"},{"DefectID":8,"Severity":"Minor"}]}', '0.375', 'DIVIDE(numerator, denominator) — the numerator is a FILTER+COUNTROWS just like the previous challenge.', 'DIVIDE(COUNTROWS(FILTER(Defects, Defects[Severity] = "Critical")), COUNTROWS(Defects))', 'medium');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL300', 'dax', 'Time Intelligence: SAMEPERIODLASTYEAR', 'The Sales table has a Year column. Write a measure that returns total Amount for the prior year relative to the latest year present, using CALCULATE + SAMEPERIODLASTYEAR (simplified: this engine treats SAMEPERIODLASTYEAR(Sales[Year]) as "filter to MAX(Year) - 1").', 'CALCULATE(SUM(Sales[Amount]), /* time intelligence function */)', '{"primaryTable":"Sales","rows":[{"Year":2023,"Amount":500},{"Year":2023,"Amount":300},{"Year":2024,"Amount":700},{"Year":2024,"Amount":400}]}', '800', 'SAMEPERIODLASTYEAR takes a date/year column reference as its only argument, and must be used as a filter argument inside CALCULATE.', 'CALCULATE(SUM(Sales[Amount]), SAMEPERIODLASTYEAR(Sales[Year]))', 'hard');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL200', 'powerfx', 'Filter: Low Stock Alert', 'Write a Power Fx formula that returns only Inventory rows where Quantity is below ReorderPoint — the data a "Reorder Needed" gallery should show.', 'Filter(Inventory, /* condition */)', '{"tables":{"Inventory":[{"Item":"Bolt","Quantity":5,"ReorderPoint":10},{"Item":"Nut","Quantity":50,"ReorderPoint":10},{"Item":"Washer","Quantity":8,"ReorderPoint":20},{"Item":"Screw","Quantity":100,"ReorderPoint":30}]}}', '[{"Item":"Bolt","Quantity":5,"ReorderPoint":10},{"Item":"Washer","Quantity":8,"ReorderPoint":20}]', 'Field names inside Filter''s condition are referenced bare (no table prefix): Quantity < ReorderPoint.', 'Filter(Inventory, Quantity < ReorderPoint)', 'easy');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL200', 'powerfx', 'LookUp: Find a Machine by ID', 'Write a Power Fx formula that returns the single Machines record where MachineID equals 3.', 'LookUp(Machines, /* condition */)', '{"tables":{"Machines":[{"MachineID":1,"Name":"CNC-A"},{"MachineID":2,"Name":"CNC-B"},{"MachineID":3,"Name":"Press-C"}]}}', '{"MachineID":3,"Name":"Press-C"}', 'LookUp(<table>, <condition>) returns the FIRST matching record, not a table.', 'LookUp(Machines, MachineID = 3)', 'easy');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL200', 'powerfx', 'Patch: Close Out an Inspection', 'Use Patch to update the Inspections record with InspectionID = 2, setting its Status to "Passed". Use LookUp inside Patch to find the base record.', 'Patch(Inspections, /* base record */, { /* updates */ })', '{"tables":{"Inspections":[{"InspectionID":1,"Status":"Pending"},{"InspectionID":2,"Status":"Pending"},{"InspectionID":3,"Status":"Passed"}]}}', '{"InspectionID":2,"Status":"Passed"}', 'Patch(<table>, LookUp(<table>, <id condition>), { Field: "NewValue" }) is the classic update pattern.', 'Patch(Inspections, LookUp(Inspections, InspectionID = 2), { Status: "Passed" })', 'medium');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL200', 'powerfx', 'CountIf: Critical Defect Count', 'Count how many Defects rows have Severity equal to "Critical" using CountIf.', 'CountIf(Defects, /* condition */)', '{"tables":{"Defects":[{"DefectID":1,"Severity":"Critical"},{"DefectID":2,"Severity":"Low"},{"DefectID":3,"Severity":"Critical"},{"DefectID":4,"Severity":"Medium"},{"DefectID":5,"Severity":"Critical"}]}}', '3', 'CountIf(<table>, <condition>) is a single combined count+filter function — no nested Filter/CountRows needed.', 'CountIf(Defects, Severity = "Critical")', 'easy');
    INSERT INTO challenges (track, engine, title, prompt, starter_code, mock_data, expected_result, hint, solution, difficulty) VALUES ('PL200', 'powerfx', 'Collect: Log a New Defect', 'Use Collect to add a new record to the Defects table with DefectID 2 and Severity "High".', 'Collect(Defects, { /* new record */ })', '{"tables":{"Defects":[{"DefectID":1,"Severity":"Low"}]}}', '{"DefectID":2,"Severity":"High"}', 'Collect(<table>, { Field1: value1, Field2: value2 }) appends a new record and returns it.', 'Collect(Defects, { DefectID: 2, Severity: "High" })', 'easy');
    -- case studies (explicit ids so case_study_questions can reference them)
    INSERT INTO case_studies (id, track, title, scenario, constraints, stakeholders) VALUES (1, 'PL200', 'TorqueWorks Manufacturing — Quality Management Platform', 'TorqueWorks Manufacturing operates 4 production plants that make precision automotive fasteners. Quality defects are currently tracked in spreadsheets emailed between plants, causing slow corrective action and inconsistent severity reporting to corporate leadership.

You have been engaged as the Power Platform Functional Consultant to design a Dataverse-based Quality Management solution. Leadership wants real-time visibility into defects across all plants, while each plant must only see and manage its own operational data. Floor inspectors need a mobile-friendly way to log defects even in low-connectivity areas of the plant (near the loading dock, inspectors frequently lose WiFi). External suppliers must be able to respond to corrective actions assigned to them without ever seeing another supplier''s data.', '["Use native Power Platform capabilities wherever possible; minimize custom code.","Supplier portal users must never see data belonging to other suppliers.","Must support offline defect logging for areas without connectivity.","Critical-severity defects must trigger a notification and corrective action record within approximately 5 minutes of creation.","The security model must scale to additional plants being onboarded later without being redesigned."]', '[{"name":"Maria Chen","role":"VP of Quality","ask":"Real-time defect visibility across all 4 plants, with drill-down to the machine level."},{"name":"Raj Patel","role":"Plant IT Manager","ask":"Each plant manager should only see their own plant''s data; corporate quality team needs to see every plant."},{"name":"Dana Ortiz","role":"Supplier Relations Lead","ask":"External suppliers must submit corrective action responses via a portal, without ever accessing internal systems directly, and without seeing other suppliers'' data."},{"name":"Tom Reyes","role":"Floor Supervisor","ask":"An easy mobile app for inspectors to log defects even when WiFi drops near the loading dock."}]');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (1, 1, 'Which security architecture satisfies both "each plant manager sees only their own plant" AND "corporate quality sees every plant," while scaling cleanly as new plants are added?', '["Give every user the System Administrator role and rely on manual training not to look at other plants'' data","Create a Business Unit per plant (optionally under a Corporate parent BU), assign Plant Manager roles at the Business Unit access level, and assign the Corporate Quality role at the Organization (or Parent:Child) access level","Share every Defect record individually with every user who should see it","Put all users in a single Business Unit and rely on Field Security Profiles to hide rows"]', 1, 'Business Units are the native Dataverse mechanism for structural, scalable data isolation. One BU per plant (optionally nested under a Corporate BU) lets Plant Manager roles be scoped to Business Unit (their own plant only), while the Corporate Quality role is scoped to Organization or Parent:Child Business Units to see everything — and onboarding a new plant is just adding another BU, with no redesign of the security model.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (1, 2, 'Which feature should visually guide a Defect record through Reported -> Investigating -> Corrective Action Assigned -> Verified -> Closed, directly on the form?', '["A Dashboard","A Business Process Flow","A Quick Create Form","A SharePoint document library"]', 1, 'Business Process Flows render a stage-based progress bar on the form and enforce required fields per stage, which is exactly the "guided lifecycle" requirement for the Defect record.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (1, 3, 'Which Canvas App design approach correctly supports Tom Reyes''s requirement for inspectors to keep logging defects when WiFi drops near the loading dock?', '["Nothing needs to change; Canvas Apps always work offline automatically","Explicitly implement offline data handling (e.g., local collections populated via LoadData/SaveData, or a configured offline profile) so the app can read/write without connectivity and sync later","Tell inspectors to walk back to an area with WiFi before logging defects","Increase the non-delegable row limit setting in app settings"]', 1, 'Canvas Apps do not support offline scenarios automatically — offline capability must be deliberately engineered (local caching with SaveData/LoadData, or an offline profile), which is the documented approach for disconnected mobile data capture.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (1, 4, 'Which automation design satisfies the ~5-minute SLA: notify the plant manager AND auto-create a CorrectiveAction record whenever a Defect is created with Severity = Critical?', '["A scheduled cloud flow that runs once every night and checks for new critical defects","A Dataverse-triggered cloud flow (\"When a row is added\"), filtered to Severity = Critical, that sends a notification and creates the CorrectiveAction record in the same run","A business rule that shows an on-form warning message","A manual flow the plant manager has to remember to run"]', 1, 'A Dataverse row-creation trigger fires within moments of the record being saved, so filtering to Critical severity and chaining a notification + record-creation action in the same flow run comfortably satisfies a 5-minute SLA — unlike a nightly schedule (far too slow), a business rule (cannot send notifications or create related records), or a manual trigger (not automatic).');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (1, 5, 'Which combination of Power Pages configuration correctly satisfies "suppliers authenticate with their own company identity" AND "suppliers only see their own corrective actions"?', '["Local portal accounts for every supplier employee, with a single Table Permission scoped Globally to CorrectiveAction","An external/federated identity provider (e.g., the supplier''s own Microsoft Entra ID tenant via OpenID Connect) for authentication, combined with a Table Permission on CorrectiveAction scoped by relationship to the supplier''s Account (Contact/Parent scope), assigned through Web Roles","Anonymous access with no authentication at all, relying on obscure URLs","A Power Automate flow that emails a PDF of all corrective actions to every supplier weekly"]', 1, 'Federated authentication (external identity provider via OpenID Connect) lets suppliers log in with their own organizational credentials, while a relationship-scoped Table Permission (not Global) assigned via Web Roles ensures each supplier only sees CorrectiveAction rows tied to their own Account — satisfying both the authentication and the data-isolation requirement.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (1, 6, 'A junior consultant proposes configuring the CorrectiveAction Table Permission scope as "Global" in the supplier portal to "keep things simple." What is the consequence, and does it satisfy the case study''s constraints?', '["No consequence — Global scope is the recommended default for all Power Pages tables","It violates the explicit constraint that suppliers must never see another supplier''s data, because Global scope grants access to every row in the table to any authenticated user holding that permission","Global scope only affects internal users, not external portal users, so it is safe here","Global scope would prevent the portal from loading any data at all"]', 1, 'A "Global" Table Permission scope grants access to ALL rows in the table for anyone holding that permission — directly violating the stated constraint that suppliers must never see another supplier''s corrective actions. The correct scope ties access to a relationship (e.g., Account/Parent), as identified in the previous question.');
    INSERT INTO case_studies (id, track, title, scenario, constraints, stakeholders) VALUES (2, 'PL300', 'Brightline Industrial — Executive Quality & Operations Analytics', 'Brightline Industrial operates 6 plants (grouped into 2 regions) producing automotive components, and has just completed a Dataverse-based Quality Management rollout (tracking Defects, Inspections, and Machines). Separately, a legacy on-premises SQL Server data warehouse holds historical Production and Cost data going back 5 years.

Leadership wants ONE governed Power BI solution that blends both sources so Plant Managers, Regional Directors, and Executives can each see operations and quality data at the altitude appropriate to their role — without maintaining 40+ separate reports or manually-managed security roles.', '["Row-level security must scale as plants/regions are added, without manually creating a role per plant.","The on-premises SQL Server source requires a gateway for scheduled refresh.","Cost data is sensitive and must stay protected even if a report link is accidentally shared externally.","Shop floor displays must be readable at a glance and colorblind-accessible.","One shared dataset/report set should serve all three audience tiers (Plant Manager, Regional Director, Executive)."]', '[{"name":"Elena Vasquez","role":"CFO","ask":"A single trusted dataset, refreshed every 4 hours, with proper protection since cost data is included."},{"name":"Plant Managers (40+)","role":"Shop Floor Leadership","ask":"Legible, colorblind-safe shop-floor dashboards with only the most important KPIs visible at a glance."},{"name":"Regional Directors","role":"Regional Leadership","ask":"A drill hierarchy from Region to Plant to Machine."},{"name":"Data Governance Officer","role":"Governance","ask":"Security driven dynamically by each user''s identity — not a manually managed role per plant, since there are 40+ plant managers today and more plants are planned."}]');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (2, 1, 'Which Row-Level Security approach satisfies "scales to 40+ plant managers and multiple regional directors without manually creating a role per plant"?', '["Create one static RLS role per plant (6 roles) and one per region (2 roles), manually assigning each of the 40+ users to their matching role","Dynamic RLS: a single DAX rule using USERPRINCIPALNAME() joined to a Plant/Region-to-User mapping table, so the same rule automatically scopes each logged-in user to their own plant or region","Disable RLS and rely on separate workspaces per plant instead","Ask every plant manager to manually filter the report themselves and trust them not to look at other plants"]', 1, 'Dynamic RLS (USERPRINCIPALNAME() or USERNAME() joined against a mapping table of users-to-plants/regions) lets ONE rule automatically scope data correctly for any user, scaling to new plants/users by just adding mapping rows — exactly the scalability the governance officer requires, unlike static per-plant roles which require manual role creation and per-user assignment that grows linearly with plant count.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (2, 2, 'Machines can contain child sub-assemblies which are themselves tracked as Machine rows with a ParentMachineID. Which modeling technique correctly supports a Region -> Plant -> Machine (-> sub-assembly) drill hierarchy for the Regional Directors?', '["A single flat table with no relationships, relying on text concatenation for hierarchy labels","A self-referencing parent-child structure on Machine (ParentMachineID), flattened into levels using PATH()-based DAX functions, combined with standard one-to-many relationships from Region to Plant to Machine","Row-level security rules to represent the hierarchy","A many-to-many relationship between Region and Machine directly, skipping Plant entirely"]', 1, 'The Region -> Plant -> Machine chain is modeled with standard one-to-many conformed-dimension relationships, while the self-referencing Machine sub-assembly relationship specifically needs PATH()-based parent-child DAX functions to flatten into navigable hierarchy levels — these are two distinct, well-documented modeling techniques used together here.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (2, 3, 'Write the measure for "Critical Defect Rate" (Critical-severity defects divided by total defects) so that it never throws an error when a plant has zero defects in the current filter context.', '["Critical Defect Rate := COUNTROWS(FILTER(Defects, Defects[Severity] = \"Critical\")) / COUNTROWS(Defects)","Critical Defect Rate := DIVIDE(COUNTROWS(FILTER(Defects, Defects[Severity] = \"Critical\")), COUNTROWS(Defects))","Critical Defect Rate := SUM(Defects[Severity])","Critical Defect Rate := AVERAGE(Defects[Severity])"]', 1, 'DIVIDE() safely handles a zero (or blank) denominator by returning BLANK() (or an optional alternate value) instead of throwing a divide-by-zero error, which the plain "/" operator in option 1 would risk when a plant has zero defects. Severity is a text/category column, so SUM/AVERAGE on it are not valid.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (2, 4, 'What must be configured so the Production/Cost dataset can refresh automatically every 4 hours from the on-premises SQL Server warehouse?', '["Nothing extra — cloud-hosted Power BI can reach any on-premises server directly by default","An On-premises Data Gateway installed and registered, linked to the dataset''s data source credentials, with Scheduled Refresh configured at the required interval","Export the SQL Server data to CSV manually every 4 hours and re-upload it","Switch the report to \"Publish to Web\" so it refreshes continuously"]', 1, 'The Power BI Service cannot reach an on-premises SQL Server directly; an On-premises Data Gateway must be installed and registered as the secure bridge, after which Scheduled Refresh can be configured for the required interval — this is the only option that is both automated and supported.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (2, 5, 'Elena Vasquez (CFO) is concerned that a report containing cost data could be mistakenly shared outside the company. What control should be applied to enforce protection even if that mistake happens?', '["A verbal reminder to the report team to \"be careful\"","A Sensitivity Label (via Microsoft Purview Information Protection) applied to the dataset/report that technically enforces restrictions such as blocking external sharing or applying encryption","Renaming the report to include the word \"Internal Only\"","Hiding the cost visuals behind a bookmark that users could still unhide"]', 1, 'Sensitivity labels are the enforced, technical governance control — unlike naming conventions or verbal reminders, a sensitivity label with protection settings can actually block or restrict external sharing and apply encryption at the platform level, regardless of user intent or mistakes.');
    INSERT INTO case_study_questions (case_study_id, step_order, question_text, options, correct_index, explanation) VALUES (2, 6, 'Plant Managers report their shop-floor dashboard feels cluttered, and a colorblind supervisor cannot distinguish "Critical" (red) from "Normal" (green) status tiles. The design also needs to keep machine-level detail available without crowding the main page. What combination of changes should you make?', '["Add more KPI tiles so nothing is \"missing,\" keep status purely color-coded, and put everything on one page","Reduce the page to the few most critical KPIs, pair the Critical/Normal status with a non-color cue (icon or text label) using a colorblind-safe palette, and move machine-level detail to a drillthrough page","Switch all charts to 3D for visual interest","Remove all visuals except a single large number tile"]', 1, 'This combines three documented best practices: minimizing default visible KPIs to reduce clutter and cognitive load, never relying on color alone (pairing with icons/text and using colorblind-safe palettes) for status meaning, and using drillthrough to keep detailed information available without cluttering the primary shop-floor view.');
    PERFORM setval(pg_get_serial_sequence('case_studies', 'id'), (SELECT COALESCE(MAX(id), 1) FROM case_studies));
    -- flashcards
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Power Fx', 'Patch()', 'Creates or updates a record in a data source. Example: Patch(Inventory, LookUp(Inventory, ID=1), { Quantity: 25 }).');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Power Fx', 'LookUp()', 'Returns the FIRST record from a table matching a condition (not a table of results).');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Power Fx', 'Filter() vs Search()', 'Filter uses a logical condition and can delegate; Search performs a text-contains search across specified columns.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Platform Limits', 'Default non-delegable row limit in Canvas Apps', '500 rows by default; configurable up to 2,000 in app settings — but delegable queries process the FULL dataset regardless.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Dataverse', 'Rollup column recalculation', 'Recalculated automatically by the system roughly every 12 hours, or triggered manually/on-demand.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Security', 'Business Unit access level', 'Grants access to records owned by any user within the SAME Business Unit as the current user.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Security', 'Field Security Profile', 'Grants Read/Create/Update rights to a specific secured column; assigned to users or teams.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Security', 'Owner Team vs Access Team', 'Owner Teams can own records and have security roles assigned directly. Access Teams gain access only via record sharing based on an Access Team Template.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Dataverse', 'Business Process Flow (BPF)', 'A visual, stage-based guided process rendered at the top of the form, enforcing required fields per stage.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Dataverse', 'Alternate Key', 'A unique, business-meaningful column (or combination) that lets external systems upsert records via the Web API without needing the internal GUID.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Dataverse', 'Configurable Cascading', 'A relationship behavior where each action (Assign, Share, Reparent, Delete, Deactivate...) can cascade independently.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Dataverse', 'Plug-in PreOperation stage', 'Synchronous pipeline stage running BEFORE the database operation commits — can cancel/block the save with an exception.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Power Automate', 'Concurrency Control', 'Lets Apply to each iterations (or trigger runs) execute in parallel instead of strictly sequentially, speeding up large independent loops.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Power Pages', 'Table Permission scopes', 'Global, Contact, Account, Parent, Self — determine which rows a Web Role can access on a table.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Security', 'Manager Hierarchy Security', 'Automatically grants managers Read/Write access to records owned by their direct and indirect subordinates, based on the Manager field.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Model-Driven Apps', 'Quick Create Form', 'A simplified, single-column form for rapid record creation, usually shown in a side panel.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Model-Driven Apps', 'Editable Grid', 'A view control that enables inline, multi-record editing without opening each record''s form.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Platform', 'Environment Variable', 'A reusable configuration value (text, number, JSON, or connection reference) that can differ per environment (dev/test/prod) without hardcoding values in solution components.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Canvas Apps', 'Delegation', 'The ability for Canvas Apps to push Filter/Sort operations to the data source server, so the FULL dataset is processed, not just the locally cached page.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL200', 'Dataverse', 'Choice vs Choices column', 'Choice (Option Set) allows exactly one selected value. Choices (Multi-select Option Set) allows multiple values stored together per row.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'CALCULATE()', 'Evaluates an expression in a MODIFIED filter context; filter arguments replace existing filters on the same column(s).');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'SUMX()', 'Iterates row-by-row over a table, evaluates an expression per row (row context), then sums the per-row results.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'DIVIDE()', 'Safe division: returns BLANK() (or a specified alternate value) instead of erroring when the denominator is 0 or blank.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'SAMEPERIODLASTYEAR()', 'Returns dates shifted back exactly one year from the current date filter context; used inside CALCULATE for year-over-year comparisons.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'VAR / RETURN', 'Defines a named intermediate value computed once and reused — improves DAX readability and avoids redundant recalculation.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'DISTINCTCOUNT()', 'Counts the number of unique (non-duplicate) values in a column.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'Filter context vs Row context', 'Filter context = active filters (slicers, visuals, CALCULATE) affecting a calculation. Row context = the "current row" during row-by-row iteration (e.g., inside SUMX).');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'DAX', 'PATH() family', 'Flattens a self-referencing parent-child hierarchy into a delimited ancestor-ID string; used with PATHITEM/PATHLENGTH to build navigable levels.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Data Modeling', 'Star Schema', 'Central fact table(s) surrounded by dimension tables, related one (dimension) to many (fact) — optimized for analysis and performance.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Data Modeling', 'Conformed Dimension', 'A single shared dimension table (e.g., Date) connected to multiple fact tables, ensuring consistent filtering/labels across all of them.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Data Preparation', 'Query Folding', 'Power Query pushes transformation steps down to execute AT the source (e.g., as SQL), instead of pulling all rows and transforming locally — critical for refresh performance.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Data Modeling', 'Import vs DirectQuery', 'Import loads a compressed in-memory copy (VertiPaq), refreshed on a schedule, generally fastest for analytics. DirectQuery queries the source live every interaction — real-time but performance-bound by the source.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Governance & RLS', 'Dynamic RLS', 'Row-Level Security using USERPRINCIPALNAME()/USERNAME() joined to a mapping table, so ONE rule automatically scopes data per logged-in user — scales without per-user static roles.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Governance & RLS', 'Sensitivity Label', 'A Microsoft Purview Information Protection label applied to Power BI content that can technically ENFORCE protections like blocking external sharing or encryption.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Visualizations', 'Bookmark', 'Captures and restores a specific report state (filters, slicer selections, visibility) — recallable via a button.');
