    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Governance & RLS', '"View As Roles"', 'A Power BI Desktop Modeling-tab feature to preview the report as a specific RLS role (optionally impersonating a user) before publishing.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Data Preparation', 'Dataflow', 'A reusable, centrally governed Power Query ETL pipeline whose OUTPUT can be shared as a source across multiple datasets.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Governance & RLS', 'Workspace vs App', 'A workspace is the collaborative authoring/backstage area. An App is a curated, read-optimized package PUBLISHED from a workspace for a wider consumer audience.');
    INSERT INTO flashcards (track, category, front, back) VALUES ('PL300', 'Data Modeling', 'Bidirectional cross-filter risk', 'Can introduce ambiguous/circular filter propagation paths and degrade query performance — use single-direction by default; use bidirectional sparingly and intentionally.');
